// COMP3123 - Assignment 1
// Automated tests for User Signup

// Test 1: Verify successful registration status
pm.test("Signup returns 201 Created", function () {
    pm.response.to.have.status(201);
});

// Test 2: Verify success message
pm.test("Signup returns success message", function () {
    const response = pm.response.json();

    pm.expect(response.message)
        .to.eql("User registered successfully");
});

// Test 3: Verify user information is returned
pm.test("Signup returns user ID, username and email", function () {
    const response = pm.response.json();

    pm.expect(response.user.id).to.exist;
    pm.expect(response.user.username).to.eql(
        pm.collectionVariables.get("username")
    );
    pm.expect(response.user.email).to.eql(
        pm.collectionVariables.get("email")
    );
});

// Test 4: Verify password is not exposed
pm.test("Signup does not expose password", function () {
    const response = pm.response.json();

    pm.expect(response.user).to.not.have.property("password");
});

// COMP3123 - Assignment 1
// Automated tests for User Login

// Test 1: Verify successful login
pm.test("Login returns 200 OK", function () {
    pm.response.to.have.status(200);
});

// Test 2: Verify success message
pm.test("Login returns success message", function () {
    const response = pm.response.json();

    pm.expect(response.message).to.eql("Login successful");
});

// Test 3: Verify JWT is returned
pm.test("Login returns JWT token", function () {
    const response = pm.response.json();

    pm.expect(response.token).to.be.a("string");
    pm.expect(response.token.split(".")).to.have.lengthOf(3);
});

// Test 4: Verify correct user information
pm.test("Login returns correct user", function () {
    const response = pm.response.json();

    pm.expect(response.user.id).to.exist;
    pm.expect(response.user.username).to.eql(
        pm.collectionVariables.get("username")
    );
});

// Save JWT for subsequent employee requests
if (pm.response.code === 200) {
    const response = pm.response.json();

    pm.collectionVariables.set("token", response.token);

    console.log("Login successful. JWT saved.");
}

// COMP3123 - Assignment 1
// Automated tests for Create Employee

// Test 1: Verify successful employee creation
pm.test("Create Employee returns 201 Created", function () {
    pm.response.to.have.status(201);
});

// Test 2: Verify success message
pm.test("Employee creation returns success message", function () {
    const response = pm.response.json();

    pm.expect(response.message)
        .to.eql("Employee created successfully");
});

// Test 3: Verify employee ID was generated
pm.test("New employee has a MongoDB ID", function () {
    const response = pm.response.json();

    pm.expect(response.employee._id).to.be.a("string");
    pm.expect(response.employee._id).to.match(/^[0-9a-fA-F]{24}$/);
});

// Test 4: Verify employee information
pm.test("Employee information is saved correctly", function () {
    const response = pm.response.json();

    pm.expect(response.employee.first_name).to.eql("Emily");
    pm.expect(response.employee.last_name).to.eql("Davis");
    pm.expect(response.employee.salary).to.eql(72000);
    pm.expect(response.employee.department).to.eql("Marketing");
});

// Save employee ID for subsequent GET, PUT, and DELETE requests
if (pm.response.code === 201) {
    const response = pm.response.json();

    pm.collectionVariables.set("employeeId", response.employee._id);

    console.log("Employee created. ID saved.");
}

