pm.test("Created employee appears in the list", function () {
    const response = pm.response.json();

    const employeeId = pm.collectionVariables.get("employeeId");

    const employeeExists = response.employees.some(
        employee => employee._id === employeeId
    );

    pm.expect(employeeExists).to.be.true;
});

